using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace Astera {
sealed partial class LibraryForm {
    readonly Label gameSettingsTitle=new Label(),gameSettingsDescription=new Label(),gameSettingsLocation=new Label();Button gameSettingsEdit,gameSettingsArtwork,gameSettingsFolder;
    void BuildGamePreferences(){var card=new Card{Dock=DockStyle.Fill,Margin=Padding.Empty};preferencesPage.Controls.Add(card);var content=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};gameSettingsTitle.Font=UiTheme.Text(22,true);gameSettingsTitle.AutoSize=true;gameSettingsTitle.Margin=new Padding(0,0,0,16);gameSettingsDescription.AutoSize=true;gameSettingsDescription.MaximumSize=new Size(850,0);gameSettingsDescription.ForeColor=Muted;gameSettingsDescription.Margin=new Padding(0,0,0,18);gameSettingsLocation.AutoSize=true;gameSettingsLocation.MaximumSize=new Size(850,0);gameSettingsLocation.ForeColor=Muted;gameSettingsLocation.Margin=new Padding(0,0,0,20);content.Controls.Add(gameSettingsTitle);content.Controls.Add(gameSettingsDescription);content.Controls.Add(gameSettingsLocation);var actions=new FlowLayoutPanel{AutoSize=true,WrapContents=true,MaximumSize=new Size(850,0)};gameSettingsEdit=Button("Game settings",delegate{Configure();});gameSettingsArtwork=Button("Game artwork",delegate{SelectLibraryTab(2);});gameSettingsFolder=Button("Open folder",delegate{OpenGameFolder();});actions.Controls.AddRange(new Control[]{gameSettingsEdit,gameSettingsArtwork,gameSettingsFolder});content.Controls.Add(actions);card.Controls.Add(content);card.Resize+=delegate{int width=Math.Max(240,card.ClientSize.Width-40);gameSettingsDescription.MaximumSize=gameSettingsLocation.MaximumSize=actions.MaximumSize=new Size(width,0);};}
    void UpdateGamePreferences(){if(gameSettingsEdit==null)return;string name=IsCustomGame?CurrentCustom.Name:IsMultiverse?"FTL: Multiverse":GameKind==1?"Star Dash":"Minecraft²";gameSettingsTitle.Text=name+" settings";gameSettingsDescription.Text=IsCustomGame?(CustomSteam(CurrentCustom)!=null||CurrentCustom.Platform=="steam"?"Steam manages this game's installation and updates. Choose its name, location and artwork here.":CurrentCustom.Platform=="itch"?"itch.io manages this game. Choose its name, install location and artwork here.":"Choose this game's name, application and artwork."):IsMultiverse?"Manage the FTL installation, Multiverse setup and backups for this game.":GameKind==1?"Choose your Star Dash application and artwork.":"Choose your Minecraft² CurseForge profile and resource-pack setup.";gameSettingsLocation.Text="Location: "+(String.IsNullOrWhiteSpace(GameFolder())?"Not linked":GameFolder());gameSettingsEdit.Enabled=gameSettingsArtwork.Enabled=!busy;gameSettingsFolder.Enabled=!busy&&Directory.Exists(GameFolder());}
    void ManageLibraryLocations(){using(var dialog=new AsteraDialog{Text="Library locations",Size=new Size(660,400),StartPosition=FormStartPosition.CenterParent}){var locations=new ScrollText{Dock=DockStyle.Fill,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.FromArgb(20,26,43),ForeColor=Color.White,BorderStyle=BorderStyle.None};var content=new Panel{Dock=DockStyle.Fill,Padding=new Padding(18)};content.Controls.Add(locations);var choose=Button("Choose itch.io apps folder…",delegate{using(var picker=new ExplorerFolderDialog{Description="Choose the itch.io apps folder",SelectedPath=store.Settings.ItchAppsRoot})if(picker.ShowDialog(dialog)==DialogResult.OK){store.Settings.ItchAppsRoot=picker.SelectedPath;store.Save();locations.Text+="\r\nitch.io: "+picker.SelectedPath;}});choose.Dock=DockStyle.Bottom;content.Controls.Add(choose);dialog.Controls.Add(content);dialog.Shown+=async delegate{var roots=await System.Threading.Tasks.Task.Run(()=>PlatformLibraries.Steam(SteamArtwork.Roots()).Select(g=>Directory.GetParent(g.Folder).Parent.Parent.FullName).Distinct(StringComparer.OrdinalIgnoreCase).ToArray());if(!dialog.IsDisposed)locations.Text="Steam libraries\r\n"+String.Join("\r\n",roots)+"\r\n\r\nitch.io apps\r\n"+(String.IsNullOrEmpty(store.Settings.ItchAppsRoot)?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"itch","apps"):store.Settings.ItchAppsRoot);};dialog.ShowDialog(this);}}
}
}
